export function withSpan<T>(
  callback: (span: LiveSpan) => T | Promise<T>,
  options?: Omit<SpanOptions, 'parent'>,
): T | Promise<T> {
  if (isTracingEnabledInContext() === false) {
    return callback(new NoOpSpan());
