 * Utilities for reading and interpreting Codex rollout JSONL transcripts.
 *
 * Codex persists each session as an append-only JSONL file where every line is
 * a {@link RolloutLine} with a `type` and a `payload`. Tool invocations and
 * their outputs are flat and linked by `call_id` (not nested), and
 * `event_msg` records such as `token_count` are interspersed throughout the
 * stream.
 */

import * as fs from 'fs';
import type { ContentBlock, RolloutLine } from './types';

/** Number of nanoseconds in a single millisecond. */
const NANOSECONDS_PER_MS = 1e6;

/**
 * Read a JSONL transcript file from disk and parse each non-empty line into a
 * {@link RolloutLine}.
 *
 * @param filePath Path to the rollout JSONL file.
 * @returns One parsed record per line.
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const raw = fs.readFileSync(filePath, 'utf-8');
  return raw
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as RolloutLine);
}

/**
 * Parse an ISO 8601 timestamp string into an integer number of nanoseconds
 * since the Unix epoch.
 *
 * @param input An ISO 8601 timestamp, or null/undefined/empty string.
 * @returns The timestamp in nanoseconds, or null when the input is
 *   null, undefined, empty, or not a parseable timestamp.
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input == null || input === '') {
    return null;
  }

  const ms = Date.parse(input);
  if (Number.isNaN(ms)) {
    return null;
  }

  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content field.
 *
 * @param content An array of content blocks, a plain string, or undefined.
 * @returns The joined text of all blocks (separated by newlines) when given an
 *   array, the string unchanged when given a string, or '' when undefined.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }

  if (typeof content === 'string') {
    return content;
  }

  return content
    .filter((block) => block != null && typeof block.text === 'string')
    .map((block) => block.text)
    .join('\n');
}

/**
 * Find the text of the last user message in a transcript.
 *
 * @param records The transcript records.
 * @returns An object with a `text` property, or null if there is no user
 *   message.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const { type, payload } = records[i];
    if (type === 'response_item' && payload.type === 'message' && payload.role === 'user') {
      return { text: extractTextFromContent(payload.content) };
    }
  }
  return null;
}

/**
 * Return the subset of records belonging to the most recent turn: from the
 * last `task_started` event through the closing `task_complete` event,
 * inclusive.
 *
 * @param records The full transcript.
 * @returns The records of the most recent turn. The first record (when present)
 *   is the `task_started` `event_msg`.
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  let startIdx = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    if (records[i].type === 'event_msg' && records[i].payload.type === 'task_started') {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) {
    return [];
  }

  // The turn ends at the last task_complete event at or after the start.
  let endIdx = records.length - 1;
  for (let i = records.length - 1; i >= startIdx; i--) {
    if (records[i].type === 'event_msg' && records[i].payload.type === 'task_complete') {
      endIdx = i;
      break;
    }
  }

  return records.slice(startIdx, endIdx + 1);
}

/**
 * Locate the `token_count` event in the transcript and extract token usage.
 * When several are present, the most recent (cumulative) totals are used.
 *
 * @param records The transcript records.
 * @returns The input, output and total token counts, or null if no
 *   `token_count` event exists.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  let tokenPayload: RolloutLine['payload'] | null = null;
